<template><div class="page"><AppNav/><main class="wrap"><section class="chat panel"><header><button class="back" @click="router.push('/messages')">← 返回协作</button><div class="agent-avatar">{{ owner.agent_avatar || '✦' }}</div><div><span class="eyebrow">FRIEND'S LEARNING AGENT</span><h1>{{ owner.agent_name || '学习 Agent' }}</h1><p>{{ owner.name }} 的 Agent · 已获主人授权</p></div></header><p class="notice">你的问题会发送给 {{ owner.name }} 配置的模型；该 Agent 不会读取或泄露其主人的课表、计划、学习画像与私聊内容。</p><div ref="box" class="messages"><div v-if="!messages.length" class="empty">可以向这位学习伙伴的 Agent 询问课程知识、复习方法或公开学习资料。</div><article v-for="(message,index) in messages" :key="index" :class="message.role"><span>{{ message.role === 'user' ? '我' : (owner.agent_name || 'Agent') }}</span><p>{{ message.content }}</p></article><article v-if="loading" class="assistant"><span>{{ owner.agent_name || 'Agent' }}</span><p>正在思考…</p></article></div><form @submit.prevent="send"><textarea v-model="input" :disabled="loading" placeholder="输入要向好友 Agent 提问的内容" @keydown.enter.exact.prevent="send"/><button class="primary" :disabled="loading || !input.trim()">{{ loading ? '思考中…' : '发送' }}</button></form></section></main></div></template>
<script setup>
import { nextTick, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import AppNav from '../components/AppNav.vue'
import { api, post } from '../utils/api'
const route=useRoute(),router=useRouter(),owner=ref({}),messages=ref([]),input=ref(''),loading=ref(false),box=ref(null);const id=route.params.id
async function load(){const [profile,history]=await Promise.all([api(`/users/${id}/profile`),api(`/friend-agents/${id}/messages`)]);owner.value=profile.user;messages.value=history;scroll()}
async function send(){const content=input.value.trim();if(!content||loading.value)return;loading.value=true;input.value='';messages.value.push({role:'user',content});scroll();try{const data=await post(`/friend-agents/${id}/messages`,{content});messages.value.push({role:'assistant',content:data.answer})}catch(e){messages.value.pop();ElMessage.error(e.message)}finally{loading.value=false;scroll()}}
function scroll(){nextTick(()=>{if(box.value)box.value.scrollTop=box.value.scrollHeight})}onMounted(()=>load().catch(e=>{ElMessage.error(e.message);router.push('/messages')}))
</script>
<style scoped>.wrap{max-width:900px;margin:auto;padding:35px 5vw}.panel{background:#fffdfa;border:1px solid #f1e2d8;border-radius:24px;box-shadow:0 10px 30px #9f4c2b0d}.chat{height:calc(100vh - 142px);min-height:560px;max-height:760px;display:flex;flex-direction:column;overflow:hidden}.chat header{display:flex;align-items:center;gap:12px;padding:22px 26px}.back{border:0;background:#fff0e4;color:#a95638;border-radius:11px;padding:8px;cursor:pointer}.agent-avatar{width:42px;height:42px;border-radius:15px;display:grid;place-items:center;background:#eee1f5;color:#79578c;font-size:23px}.eyebrow{font-size:11px;color:#ad8b7a;font-weight:800;letter-spacing:1px}.chat h1{margin:3px 0;color:#633c2c;font-size:23px}.chat header p{margin:0;color:#9c7c6e;font-size:13px}.notice{margin:0;padding:10px 26px;background:#fff5e9;color:#8e6d5a;font-size:12px;line-height:1.5}.messages{flex:1;min-height:0;padding:20px 28px;overflow-y:auto;overscroll-behavior:contain;background:#fffcf9}.messages article{max-width:78%;margin:12px 0;padding:11px 14px;border-radius:16px;background:#f4e9f8;color:#5e496b;line-height:1.6}.messages article.user{margin-left:auto;background:#c96d42;color:#fff}.messages span{font-size:11px;font-weight:800}.messages p{margin:3px 0 0;white-space:pre-wrap;overflow-wrap:anywhere}.empty{text-align:center;color:#a08475;margin:110px 10%}.chat form{padding:16px 22px;display:flex;gap:10px}.chat textarea{flex:1;resize:none;border:1px solid #ead8cd;border-radius:15px;padding:11px;font:inherit}.primary{align-self:end;background:#c96d42;color:#fff;border:0;border-radius:13px;padding:11px 17px;font-weight:700;cursor:pointer}@media(max-width:600px){.wrap{padding:15px}.chat{height:calc(100vh - 105px);min-height:0;max-height:none}.chat header{padding:17px}.messages{padding:15px}}</style>
